func TestReachHandlesCycles(t *testing.T) {
	g := NewGraph()
	for i := 1; i <= 3; i++ {
		g.AddVertex(i, nil)
	}
	g.AddEdge(1, 2, "x")
	g.AddEdge(2, 3, "x")
	g.AddEdge(3, 1, "x")
	if got := g.Reach(1, "x", Outgoing); !reflect.DeepEqual(got, []int{1, 2, 3}) {
		t.Errorf("Reach sur un cycle = %v, attendu [1 2 3] (et surtout : terminer)", got)
