func TestMigrated(t *testing.T) {
	g := world(t)
	if got := g.Migrated("United States", "Europe"); !reflect.DeepEqual(got, []string{"Lucy"}) {
		t.Errorf("Migrated(US → Europe) = %v, attendu [Lucy]", got)
	}
