	want := []IndexEntry{{"k00000", 0}, {"k00008", 4}, {"k00016", 8}}
	if !reflect.DeepEqual(idx, want) {
		t.Errorf("index = %v, attendu %v", idx, want)
	}
	if BuildSparseIndex(tbl, 0) != nil || BuildSparseIndex(nil, 4) != nil {
		t.Error("every < 1 ou table vide : nil")
