	// Dans l'autre ordre, la recherche par prénom fonctionne.
	f := NewConcat(first, last)
	for _, r := range people() {
		f.Add(r)
	}
	if got := f.Lookup("Marie"); !reflect.DeepEqual(got, []int{4, 1, 6, 3}) {
		t.Errorf("index (prénom, nom) : %v, attendu [4 1 6 3]", got)
