  await Promise.all(Array.from({ length: 200 }, () => e.exec(increment)));
  let got = 0;
  await e.exec((s) => { got = s.get('counter'); });
  eq(got, 200, 'compteur (aucune mise à jour ne doit être perdue)');
});

