  lm.acquire(1, 'x', 'shared');
  lm.acquire(2, 'x', 'exclusive'); // attend
  eq(lm.acquire(3, 'x', 'shared'), 'waiting', 'un nouveau lecteur ne doit pas doubler un écrivain déjà en attente');
