  up.acquire(1, 'x', 'shared');
  up.acquire(2, 'x', 'shared');
  eq(up.acquire(1, 'x', 'exclusive'), 'waiting', '1 veut promouvoir et attend 2');
  eq(up.acquire(2, 'x', 'exclusive'), 'deadlock', 'deux promotions simultanées s’attendent mutuellement');
});

