    }
}

class Plain { String x }

class Account {
    String username
    String password
    Integer balance
    static constraints = {
        username size: 3..8
        password validator: { pwd, acct -> pwd != acct.username }
        balance  nullable: true, validator: { v -> v >= 0 }
    }
}

class Codes {
    String a
    String b
    String c
    static constraints = {
        a validator: { v -> v == 'ok' ? true : 'codes.a.invalide' }
        b nullable: true, validator: { v, o -> v == o.a }
        c validator: { v, o, errors ->
