 * Copié dans tests/ des TP qui vérifient des types (source : sandbox/images/typescript/expect.ts).
 *
 *   type _t1 = Expect<Equals<ReturnType<typeof f>, number>>;
 *   // @ts-expect-error l'argument doit être refusé
 *   f('x');
