  eq(addVec({ x: 1, y: 2, z: 3 }, { x: 10, y: 20, z: 30 }), { x: 11, y: 22, z: 33 }, 'addVec');
});

test('sumAll : tableau, Set, générateur', () => {
  eq(sumAll([1, 2, 3]), 6, 'tableau');
  eq(sumAll(new Set([1, 2, 3])), 6, 'Set');
  eq(sumAll((function* () { yield 4; yield 5; })()), 9, 'générateur');
  eq(sumAll([]), 0, 'vide');
});

